contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put to deposit funds and set unlockTime, then attempt Collect.
    // params: deposit amount to Put, unlockTime to set, collect amount to attempt.
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(true);
        // Ensure this contract has enough balance to forward putAmount
        if (putAmount > 0) { require(address(this).balance >= putAmount); }

        // Read before values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // Call Put to deposit putAmount and set unlockTime
        // Use fallback-friendly Put call with value
        if (putAmount > 0) {
            c.Put{value: putAmount}(unlockTime);
        } else {
            // still call Put with zero value to possibly update unlockTime
            c.Put{value: 0}(unlockTime);
        }

        // Read after values prior to Collect
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBalance = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        // Collect is payable but shouldn't require value from caller; call without value
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read values after Collect attempt
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // If Collect did not revert then (a) the holder balance decreased by collectAmount
        // and (b) the contract's ether balance decreased by at least collectAmount.
        // We express this as an assertion relating observed public getters and balances.
        assert(reverted || (midBalance >= collectAmount && midBalance - afterBalance == collectAmount && midContractBalance >= afterContractBalance && midContractBalance - afterContractBalance >= collectAmount));
    }

    // accept Ether so contract can forward funds to c
    receive() external payable {}
}

contract InvMutTest {
