        } catch {
            reverted = true;
        }

        // read balance after Collect
        (, uint afterBalance) = c.Acc(address(this));

        // If Collect returned (did not revert) then the stored balance strictly decreased.
        assert(reverted || afterBalance < beforeBalance);
    }

    // helper that makes no decision but avoids compiler warnings about unused param patterns
    function collectionAllowed(uint x) internal pure returns (bool) { return true; }

