}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // putAmount: wei to deposit via Put
    // unlockTime: unlock time passed to Put
    // collectAmount: amount requested in Collect
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Deposit funds into c so there is something to collect
        c.Put{value: putAmount}(unlockTime);

        // read stored Account state before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read stored Account state after Collect
        (, uint afterBalance) = c.Acc(address(this));

        // If Collect returned (did not revert) then either:
        // - afterBalance == beforeBalance - collectAmount (normal decrease), or
        // - if collectAmount == beforeBalance then afterBalance == 0
        // We express this as: if not reverted then either afterBalance + collectAmount == beforeBalance
        // (covers exact decrease and the zero case) — but avoid underflow by using conditional when needed.
        assert(reverted || (beforeBalance >= collectAmount && afterBalance + collectAmount == beforeBalance));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // putAmount: wei to deposit via Put
    // unlockTime: unlock time passed to Put
    // collectAmount: amount requested in Collect
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Record contract balance before deposit
        uint beforeC = address(c).balance;

        // Deposit funds into c so there is something to collect later
        c.Put{value: putAmount}(unlockTime);

        // Read stored account state after Put
        (uint afterPutUnlock, uint afterPutBalance) = c.Acc(address(this));

        // Ensure there is some recorded balance to possibly collect; otherwise Collect will be a no-op
        // but we still allow trying Collect: no extra require so assertion must handle both cases.

        // Record contract balance just before Collect
        uint beforeCollectC = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record contract balance after Collect
        uint afterCollectC = address(c).balance;

        // If Collect returned (did not revert) then the contract's ETH balance must have decreased by at least collectAmount
        // (i.e., afterCollectC + collectAmount <= beforeCollectC). We express as: !reverted implies afterCollectC + collectAmount <= beforeCollectC
        assert(reverted || afterCollectC + collectAmount <= beforeCollectC);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will call Put on c with a chosen unlockTime and amount, and assert that
    // if the call does not revert then both the on-chain balance observable via
    // c.Acc(address(this)).balance and address(c).balance increase by exactly amount.
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);
        // Read before-values via public getters: Acc is public mapping, so Acc(address) returns (unlockTime,balance)
        (, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If the call reverted then nothing changed (on-chain state and contract balance remain as before).
        // If it did not revert then both the recorded holder balance and the contract's ETH balance
        // must have increased by exactly amount.
        assert(reverted
               ? (afterBal == beforeBal && afterContractBal == beforeContractBal)
               : (afterBal == beforeBal + amount && afterContractBal == beforeContractBal + amount)
        );
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first ensure the test contract has deposited at least MinSum and set unlockTime in past
    // so that Collect may succeed; then we call Collect with a provided amount and check the invariant.
    function run(uint depositUnlockTime, uint depositAmount, uint collectAmount) public payable {
        // ensure this test contract has enough ETH to fund the deposit
        require(address(this).balance >= depositAmount);
        // Read before-values
        (, uint beforeBal) = c.Acc(address(this));
        uint beforeSelfBal = address(this).balance;
        uint beforeContractBal = address(c).balance;

        // Make a Put to top up balance and set unlockTime; use a deposit that may be large
        bool putReverted;
        try c.Put{value: depositAmount}(depositUnlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Now attempt Collect of collectAmount and observe whether it reverts
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        (, uint afterBal) = c.Acc(address(this));
        uint afterSelfBal = address(this).balance;
        uint afterContractBal = address(c).balance;

        // If Collect reverted then contract and recorded balances must be unchanged since just before Collect.
        // If Collect succeeded then recorded balance decreased by collectAmount and test contract's ETH increased by collectAmount
        // and contract's ETH decreased by collectAmount.
        // Note: allow that Put might have reverted; assertion is about effect of Collect relative to the state immediately before Collect.
        assert(
            collectReverted
            ? (afterBal == (putReverted ? beforeBal : beforeBal + depositAmount) && afterSelfBal == (putReverted ? beforeSelfBal : beforeSelfBal - depositAmount) == true ? false : true) == false
            : (afterBal + collectAmount == (putReverted ? beforeBal : beforeBal + depositAmount) && afterSelfBal == (putReverted ? beforeSelfBal : beforeSelfBal - depositAmount) + collectAmount && afterContractBal + collectAmount == (putReverted ? beforeContractBal : beforeContractBal + depositAmount))
        );
    }

    // receive to accept Ether when Collect sends funds
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount is the ether we attempt to send to Put; unlockTime is arbitrary
    function run(uint unlockTime, uint depositAmount) public payable {
        // ensure this test contract has enough ETH to send depositAmount
        require(address(this).balance >= depositAmount);

        // read balances before Put
        (, uint beforeRecorded) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool putReverted;
        try c.Put{value: depositAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        (, uint afterRecorded) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Put did not revert then the recorded balance for this contract must increase by depositAmount
        // and the contract's Ether balance must also increase by depositAmount. If Put reverted then neither should increase.
        assert(putReverted ? (afterRecorded == beforeRecorded && afterContractBal == beforeContractBal)
                            : (afterRecorded == beforeRecorded + depositAmount && afterContractBal == beforeContractBal + depositAmount));
    }

    // accept Ether when Collect might send funds (not used here but safe to have)
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to collect amount `am`. We require no precondition on am; test contract must have no Ether sent here.
    function run(uint am) public payable {
        // read recorded balance before and contract balance
        (, uint balBefore) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        bool collReverted;
        try c.Collect{value:0}(am) {
            collReverted = false;
        } catch {
            collReverted = true;
        }

        (, uint balAfter) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule:
        // 1) The recorded balance for this holder is never increased by Collect (balAfter >= balBefore is allowed only if equal).
        // 2) If Collect succeeded then balAfter == balBefore - am AND contract's balance decreased by at least am (it may decrease by am when transfer succeeds).
        // 3) If Collect reverted then recorded balance and contract balance are unchanged.
        assert(
            // recorded balance never increases
            balAfter <= balBefore
            && (
                collReverted
                ? (balAfter == balBefore && contractBalAfter == contractBalBefore)
                : (balAfter + am == balBefore && contractBalAfter + am <= contractBalBefore)
            )
        );
    }

    // accept Ether if Collect sends funds to this test contract (not expected but safe)
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to send and an unlock time candidate
    function run(uint amount, uint unlock) public payable {
        require(address(this).balance >= amount);

        // Read recorded balance and contract balance before
        (, uint balBefore) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        bool putReverted;
        // Call Put with value = amount
        try c.Put{value: amount}(unlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read after-values
        (, uint balAfter) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // Assert the invariant described in the summary
        // If Put reverted -> no change. If succeeded -> contract's ether balance increased exactly by amount
        // and recorded balance increased by at least amount (contract may have saturating/other checks, but shouldn't decrease or miss funds if call succeeded)
        assert(
            putReverted
            ? (balAfter == balBefore && contractBalAfter == contractBalBefore)
            : (contractBalAfter == contractBalBefore + amount && balAfter >= balBefore && balAfter - balBefore <= contractBalAfter - contractBalBefore)
        );
    }

    // accept Ether if sent
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put with an unlock time and an amount of Ether.
    // Make function payable so test can forward Ether to c.
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Observe balance recorded in c for this contract (Acc is public mapping -> getter)
        // The auto-generated getter for mapping (address => Holder) returns the tuple (unlockTime, balance)
        // However Solidity returns multiple values; we can capture only the balance by using a tuple.
        (uint beforeUnlock, uint beforeRecordedBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt to call Put and capture whether it reverted.
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        (uint afterUnlock, uint afterRecordedBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // If Put succeeded (not reverted) then recorded balance increased by amount and contract balance increased by amount.
        // If Put reverted then recorded balance and contract balance unchanged.
        assert(
            (!reverted && afterRecordedBal == beforeRecordedBal + amount && afterContractBal == beforeContractBal + amount)
            || (reverted && afterRecordedBal == beforeRecordedBal && afterContractBal == beforeContractBal)
        );
    }

    // Allow receiving Ether so the test contract can be funded externally
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will first ensure there is sufficient recorded balance and unlock time so Collect can potentially succeed.
    // Parameters:
    //  fundAmount - amount to deposit via Put to ensure Acc[this].balance >= MinSum and >= collectAmount
    //  unlockTime  - time to set when depositing; should be <= block.timestamp to allow Collect only if block.timestamp>unlockTime
    //  collectAmount - amount to attempt to collect
    function run(uint fundAmount, uint unlockTime, uint collectAmount) public payable {
        // Ensure this test contract has Ether to forward for Put
        require(address(this).balance >= fundAmount);

        // Record before-values
        (uint beforeUnlock, uint beforeRecordedBal) = c.Acc(address(this));
        uint beforeThisBal = address(this).balance;
        uint beforeCbal = address(c).balance;

        // First, try to deposit fundAmount to c so that Acc[this].balance increases (may revert if transfer fails)
        bool putReverted;
        try c.Put{value: fundAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read after deposit values (these may have changed or not)
        (uint midUnlock, uint midRecordedBal) = c.Acc(address(this));
        uint midThisBal = address(this).balance;
        uint midCbal = address(c).balance;

        // Now attempt Collect of collectAmount and record whether it reverted
        bool collectReverted;
        try c.Collect{value:0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-collect values
        (uint afterUnlock, uint afterRecordedBal) = c.Acc(address(this));
        uint afterThisBal = address(this).balance;
        uint afterCbal = address(c).balance;

        // General rule:
        // If Collect did not revert then afterRecordedBal = midRecordedBal - collectAmount AND afterThisBal = midThisBal + collectAmount
        // If Collect reverted then recorded balances and Ether balances remain as they were just before Collect.
        // Note: We only assert this relation; Put's success/failure affects mid values but Collect's effect must obey the above.
        assert(
            (!collectReverted && afterRecordedBal == midRecordedBal - collectAmount && afterThisBal == midThisBal + collectAmount)
            || (collectReverted && afterRecordedBal == midRecordedBal && afterThisBal == midThisBal)
        );
    }

    // Allow this contract to receive Ether so it can fund Put and receive Collect
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that Put either increases the contract's ETH balance by the forwarded amount when it succeeds,
    // or leaves the contract balance unchanged when it reverts.
    // Parameters:
    //   amount - Ether to send with Put
    //   unlockTime - argument forwarded to Put
    function run(uint amount, uint unlockTime) public payable {
        require(address(this).balance >= amount);

        // Record balance of c before the call
        uint beforeC = address(c).balance;

        // Call Put and record whether it reverted
        bool putReverted;
        try c.Put{value: amount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Record balance of c after the call
        uint afterC = address(c).balance;

        // General invariant: if Put succeeded, c's balance increases exactly by amount; if reverted, it stays the same.
        assert((!putReverted && afterC == beforeC + amount) || (putReverted && afterC == beforeC));
    }

    // Allow this contract to receive Ether for funding Put
    receive() external payable {}
}

