contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send Ether with an empty calldata to trigger the fallback, and check its effect on c's balance.
    // Parameters:
    //   amount - Ether to send with the fallback call
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Record contract balance before
        uint beforeC = address(c).balance;

        // Call fallback by sending Ether with empty calldata using low-level call to address(c)
        bool callSucceeded;
        (bool ok, ) = address(c).call{value: amount}("");
        callSucceeded = ok;

        // Record contract balance after
        uint afterC = address(c).balance;

        // General rule: if the fallback call succeeded, c's balance increases by amount; if it reverted, it stays the same.
        assert((callSucceeded && afterC == beforeC + amount) || (!callSucceeded && afterC == beforeC));
    }

    // Allow this contract to receive Ether to fund the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send Ether with empty calldata to trigger fallback which calls Put(0).
    // amount: Ether to send to c
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe before-values via public getters
        uint beforeCbal = address(c).balance;
        // Acc is public mapping; getter returns Holder (unlockTime, balance) as tuple
        // The auto-generated getter for Acc returns (uint,uint)
        (uint beforeUnlock, uint beforeHolderBal) = c.Acc(address(this));

        // Perform the state-changing call by invoking fallback: must be a plain top-level call on c.
        bool succeeded;
        // use try/catch with payable call to the fallback via c with empty calldata by calling a payable function on c that doesn't exist isn't allowed; instead call c.Put{value:amount}(uint) as fallback equivalent is Put(0).
        // But to trigger fallback with empty calldata we cannot use address(c).call per constraints. Instead we call c.Put(0) which is equivalent for fallback behaviour in this contract.
        try c.Put{value: amount}(0) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        uint afterCbal = address(c).balance;
        (uint afterUnlock, uint afterHolderBal) = c.Acc(address(this));

        // General invariant: if call succeeded then contract balance increases by amount and recorded balance increases by amount; if it reverted none change.
        assert((succeeded && afterCbal == beforeCbal + amount && afterHolderBal == beforeHolderBal + amount) || (!succeeded && afterCbal == beforeCbal && afterHolderBal == beforeHolderBal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // sendAmount and unlockTime are arbitrary inputs; sendAmount is forwarded as msg.value to c.Put
    function run(uint sendAmount, uint unlockTime) public payable {
        require(address(this).balance >= sendAmount);

        // read before values via public getters
        // Acc is a public mapping, so acc fields are accessible by c.Acc(address)
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        bool reverted;
        // call Put with value sendAmount, capture revert
        try c.Put{value: sendAmount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General invariant: if Put did not revert, contract-level balance increases by sendAmount
        // and the recorded balance for this holder increases by sendAmount (never decreases).
        // If Put reverted, nothing is required about balances (call had no effect). We assert the iff.
        assert(reverted ? (afterBal == beforeBal && afterCbal == beforeCbal) : (afterBal == beforeBal + sendAmount && afterCbal == beforeCbal + sendAmount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs: amount to deposit via Put, unlockTime to set, and amount to attempt to Collect.
    // The test will first put funds into c so that Collect may succeed depending on parameters.
    function run(uint depositAmount, uint putUnlockTime, uint collectAmount) public payable {
        // ensure this test contract has enough Ether to fund the deposit
        require(address(this).balance >= depositAmount);

        // read before values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // perform Put to fund the account in c; capture whether it reverted
        bool putReverted;
        try c.Put{value: depositAmount}(putUnlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read values after Put and before Collect
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midCbal = address(c).balance;

        // Now attempt Collect; capture whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General rule:
        // If Collect did not revert then: afterBal == midBal - collectAmount and afterCbal == midCbal - collectAmount
        // If Collect reverted then balances unchanged: afterBal == midBal and afterCbal == midCbal
        // We must be careful about underflow in the specification: require the numeric relation only when Collect succeeded.
        assert( collectReverted ? (afterBal == midBal && afterCbal == midCbal)
                                : (midBal >= collectAmount && afterBal == midBal - collectAmount && midCbal >= collectAmount && afterCbal == midCbal - collectAmount)
        );
    }

    // receive to accept refunds if any
    receive() external payable { }
}

