contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We implement run to exercise Put (via explicit Put call or fallback) and assert the preservation
    // of Acc[msg.sender].balance and contract Ether balance increase on successful Put.
    function run(uint unlockTime, uint amount, bool useFallback) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Read observable before-values
        // Acc is public mapping; getter signature: function Acc(address) public view returns (uint unlockTime, uint balance);
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        if (useFallback) {
            // call fallback by sending to address(c)
            try address(c).call{value: amount}(new bytes(0)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call Put directly
            try c.Put{value: amount}(unlockTime) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule asserted:
        // If the call did not revert then:
        //  - the recorded balance for this.address increased by exactly amount (non-negative change)
        //  - the contract's Ether balance increased by exactly amount
        // If the call reverted then nothing changed in observable balances (both remain equal to before values)
        assert(
            (!reverted
                ? (afterBalance == beforeBalance + amount && afterContractBalance == beforeContractBalance + amount)
                : (afterBalance == beforeBalance && afterContractBalance == beforeContractBalance))
        );
    }

    // Allow receiving Ether if needed
    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Call Put or fallback with a chosen amount; assert the observable invariants about balances.
    function run(uint unlockTime, uint amount, bool useFallback) public payable {
        // ensure this contract can send the requested Ether
        require(address(this).balance >= amount, "insufficient test balance");

        // Read observable before-values via public getter
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        // Make the state-changing call as a top-level statement
        if (useFallback) {
            // invoke fallback by low-level call
            // Note: low-level calls return (bool, bytes)
            (bool ok, ) = address(c).call{value: amount}("\x00");
            reverted = !ok;
        } else {
            // direct external call to Put
            // Must be top-level statement
            // We cannot use try/catch on internal call; use low-level call to the function selector instead
            // Prepare calldata for Put(uint)
            bytes memory data = abi.encodeWithSignature("Put(uint256)", unlockTime);
            (bool ok, ) = address(c).call{value: amount}(data);
            reverted = !ok;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // Assert the general rule: if reverted then no observable change; else balances increased by exactly amount
        assert(
            (!reverted
                ? (afterBalance == beforeBalance + amount && afterContractBalance == beforeContractBalance + amount)
                : (afterBalance == beforeBalance && afterContractBalance == beforeContractBalance))
        );
    }

    // allow receiving Ether
    receive() external payable { }
}

