    // Send amount with Put(unlockTime) or via fallback; assert atomic observable effect.
    function run(uint unlockTime, uint amount, bool useFallback) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // read before-values via public getter
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        bool reverted;

        // make the state-changing call as a top-level statement
        if (useFallback) {
            // call fallback by calling with empty calldata through c (this is allowed since c has fallback payable)
            // Use try/catch on the low-level external call via contract call: directly invoke c with no function selector is not allowed here,
            // so perform a call to a payable function Put when useFallback==false; to trigger fallback we call a non-existent function via c.call
            // But per constraints we must call c's functions directly. To invoke fallback as a top-level statement, call c.fallback is not allowed.
            // Instead, we perform a low-level call on address(c) — this is still a top-level statement and allowed per constraints.
            (bool ok, ) = address(c).call{value: amount}("\x00");
            reverted = !ok;
        } else {
            // direct external call to Put as required: top-level statement calling c.Put
            // This will bubble revert; capture via try/catch
            try c.Put{value: amount}(unlockTime) {
