            }
        }

        // read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule: either no observable change on revert, or both balances increase by exactly amount on success
        assert(
            (!reverted
                ? (afterBalance == beforeBalance + amount && afterContractBalance == beforeContractBalance + amount)
                : (afterBalance == beforeBalance && afterContractBalance == beforeContractBalance))
