    // We will first ensure the account has at least MinSum by calling Put with enough value
    // then try Collect and assert the invariant described above.
    function run(uint unlockTime, uint depositAmount, uint collectAmount) public payable {
        // ensure this test contract can send depositAmount to c
        require(address(this).balance >= depositAmount, "insufficient test balance for deposit");
        // deposit must be >= MinSum to allow Collect path later (MinSum is 1 ether in C)
        // we don't read MinSum from c here (it's public) to allow generality, but require deposit >= 1 wei
        // however to trigger Collect success path we need deposit >= MinSum; require a reasonable lower bound
        require(depositAmount >= 1, "deposit must be >=1");

        // read before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // perform Put to set up balance and unlockTime (top-level call)
        bool putReverted;
        try c.Put{value: depositAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read after Put-values (these are before Collect)
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBalance = address(c).balance;

        // Now attempt Collect(collectAmount) and capture whether it reverts
        bool collectReverted;
        try c.Collect{value:0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after-Collect values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // If Put reverted then nothing should have changed from beforePut to afterCollect
        // Otherwise, Collect either reverts (leaving balances unchanged from mid-state) or succeeds
        // and decreases both the stored balance and the contract's ETH by exactly collectAmount.
        assert(
            putReverted
            ? (midBalance == beforeBalance && midContractBalance == beforeContractBalance && afterBalance == beforeBalance && afterContractBalance == beforeContractBalance)
            : (
                collectReverted
                ? (afterBalance == midBalance && afterContractBalance == midContractBalance)
                : (afterBalance == midBalance - collectAmount && afterContractBalance == midContractBalance - collectAmount)
              )
        );
    }

    receive() external payable { }
}

